/**
 * AI Video generator — produces short video clips via a VideoProvider (Veo via GenAIPro today).
 *
 * Reads prompts from either:
 *   - Video_Prompts.docx (dedicated file generated by the "Generate video prompts" button)
 *   - Scene_Prompts.docx (reuse the still-image scene prompts)
 *   - manual_prompts[] passed in the request
 *
 * Writes resulting .mp4 files into the project's configured video subfolder
 * (default "{code} - 10 Video Assembly Output" on new projects; legacy
 * projects keep their "{code} - 09 Video Assets" wording via project.json).
 *
 * NOTE: this is SEPARATE from the FFmpeg `video.ts` generator (which assembles finished
 * stills + narration into a final video). This generator produces the AI clips that the
 * FFmpeg assembler can later consume.
 */

import fs from 'fs/promises'
import { existsSync } from 'fs'
import path from 'path'
import * as pm from '../services/project-manager.js'
import * as jq from '../services/job-queue.js'
import { resolveSubfolderNames, assertBalanceAvailable } from '../services/utils.js'
import { parseImagePromptsDocx } from '../lib/docx-parser.js'
import { downloadVideo } from '../lib/genaipro-veo-client.js'
import { registry, resolveApiKeyForProvider } from '../providers/registry.js'
import { recordTask, hashInput } from '../services/task-manifest.js'
import { sleepCancellable, fileExistsWithContent } from '../lib/http-retry.js'
import type { GenerateVideoRequest, Job, VideoModelConfig } from '../models/types.js'

async function findEpisodeDir(projectDir: string, code: string): Promise<string | null> {
  async function walk(dir: string, depth: number): Promise<string | null> {
    if (depth > 4) return null
    try {
      const entries = await fs.readdir(dir, { withFileTypes: true })
      for (const e of entries) {
        if (!e.isDirectory()) continue
        const clean = e.name.replace(/^✅\s*/, '')
        if (clean.startsWith(`${code} - `) || clean === code) return path.join(dir, e.name)
        const found = await walk(path.join(dir, e.name), depth + 1)
        if (found) return found
      }
    } catch {}
    return null
  }
  return walk(projectDir, 0)
}

async function findFileRecursive(dir: string, filenames: string[], depth = 0): Promise<string | null> {
  if (depth > 5) return null
  try {
    const entries = await fs.readdir(dir, { withFileTypes: true })
    for (const e of entries) {
      const full = path.join(dir, e.name)
      if (e.isFile() && filenames.includes(e.name)) return full
      if (e.isDirectory()) {
        const found = await findFileRecursive(full, filenames, depth + 1)
        if (found) return found
      }
    }
  } catch {}
  return null
}

async function loadPrompts(slug: string, episodeId: string, req: GenerateVideoRequest): Promise<Array<{ number: number; title: string; prompt: string }>> {
  const code = episodeId.toUpperCase()

  if (req.prompt_source === 'manual') {
    const list = req.manual_prompts || []
    return list.map((prompt, i) => ({ number: i + 1, title: `Clip ${i + 1}`, prompt }))
      .filter(p => p.prompt.trim().length > 0)
  }

  const outputRoot = await pm.getProjectOutputRoot(slug)
  if (!outputRoot) throw new Error('Project directory not found')

  if (req.prompt_source === 'video_prompts') {
    const found = await findFileRecursive(outputRoot, [`${code}_Video_Prompts.docx`])
    if (!found) throw new Error(`Could not find ${code}_Video_Prompts.docx. Generate video prompts first.`)
    const parsed = await parseImagePromptsDocx(found)
    return parsed.scenes.length ? parsed.scenes : parsed.thumbnails
  }

  // scene_prompts fallback (reuse still-image prompts)
  const found = await findFileRecursive(outputRoot, [`${code}_Scene_Prompts.docx`, `${code}_Image_Prompts.docx`])
  if (!found) throw new Error(`Could not find scene prompts for ${code}. Generate them first.`)
  const parsed = await parseImagePromptsDocx(found)
  return parsed.scenes
}

async function loadSceneImages(slug: string, episodeId: string): Promise<Array<{ number: number; path: string }>> {
  const code = episodeId.toUpperCase()
  const outputRoot = await pm.getProjectOutputRoot(slug)
  if (!outputRoot) return []
  const names = await resolveSubfolderNames(slug, code)
  const epDir = await findEpisodeDir(outputRoot, code)
  if (!epDir) return []

  // Find the scene images folder (config-driven, honours ✅ prefix)
  let imagesDir: string | null = null
  try {
    const entries = await fs.readdir(epDir)
    for (const entry of entries) {
      if (entry.replace(/^✅\s*/, '') === names.images) {
        imagesDir = path.join(epDir, entry)
        break
      }
    }
  } catch {}
  if (!imagesDir) return []

  const result: Array<{ number: number; path: string }> = []
  const seen = new Set<number>()
  try {
    const files = (await fs.readdir(imagesDir)).sort()
    for (const file of files) {
      if (!/\.(png|jpg|jpeg|webp)$/i.test(file)) continue
      // Prefer v1 variants, fall back to first match
      const sceneMatch = file.match(/Scene(\d+)/i)
      if (!sceneMatch) continue
      const n = parseInt(sceneMatch[1])
      if (seen.has(n)) continue
      if (file.includes('_v1') || !files.some(f => f.includes(`Scene${sceneMatch[1]}`) && f.includes('_v1'))) {
        seen.add(n)
        result.push({ number: n, path: path.join(imagesDir, file) })
      }
    }
  } catch {}
  return result.sort((a, b) => a.number - b.number)
}

export async function generateAiVideo(job: Job): Promise<void> {
  const { project_slug, episode_id, params } = job
  const req = params as GenerateVideoRequest

  const config = await pm.getConfig(project_slug)
  if (!config) throw new Error('Project config not found')

  const modelId = req.model || 'veo-v2'
  const videoModels: Record<string, VideoModelConfig> = (config as any).video_models || {}
  const modelConfig = videoModels[modelId]
  if (!modelConfig) throw new Error(`Unknown video model: ${modelId}. Add one in Settings → Models.`)

  const providerId = modelConfig.provider || 'genaipro-veo'
  const providerMaybe = registry.getVideoProvider(providerId)
  if (!providerMaybe) throw new Error(`No video provider registered for: ${providerId}`)
  // Re-bind to a `!`-narrowed const so closures below (processPrompt) see
  // the non-null type — TS doesn't flow narrowing into nested async fns.
  const provider = providerMaybe!

  const apiKey = await resolveApiKeyForProvider(project_slug, provider.meta, {
    model: modelId,
    jobId: job.job_id,
  })
  if (!apiKey) throw new Error(`No API key configured for ${provider.meta.name}. Add one in Settings → API Keys.`)

  // Preflight: video clips are the most expensive thing this app submits
  // (dollars per call). Refuse up front if the provider's balance is
  // definitively zero. fal/kie expose balances; genaipro-veo doesn't, so
  // we skip the check for it and let the provider surface quota issues.
  if (providerId === 'fal') await assertBalanceAvailable('fal', apiKey)
  else if (providerId === 'kie' || providerId === 'kie-video') await assertBalanceAvailable('kie', apiKey)

  // Validate mode is supported by this model
  const mode = req.mode || 'text'
  if (!modelConfig.modes?.includes(mode)) {
    throw new Error(`Model ${modelId} does not support mode "${mode}". Supported: ${modelConfig.modes?.join(', ')}`)
  }

  const prompts = await loadPrompts(project_slug, episode_id, req)
  if (!prompts.length) throw new Error('No prompts found to generate from.')
  job.output_lines.push(`Loaded ${prompts.length} prompt(s)`)

  // For frames mode, match prompts with scene images
  let sceneImages: Array<{ number: number; path: string }> = []
  if (mode === 'frames') {
    sceneImages = await loadSceneImages(project_slug, episode_id)
    if (!sceneImages.length) throw new Error('No scene images found. Generate scene images first, or switch to text-to-video mode.')
    if (req.scene_image_filenames?.length) {
      sceneImages = sceneImages.filter(s => req.scene_image_filenames!.some(f => s.path.endsWith(f)))
    }
    job.output_lines.push(`Matched ${sceneImages.length} scene image(s)`)
  }

  // Resolve output dir via config subfolder names
  const code = episode_id.toUpperCase()
  const names = await resolveSubfolderNames(project_slug, code)
  const outputRoot = await pm.getProjectOutputRoot(project_slug)
  if (!outputRoot) throw new Error('Project directory not found')
  const epDir = await findEpisodeDir(outputRoot, code)
  if (!epDir) throw new Error(`Episode folder not found for ${code}. Create the episode (via script or ideas) first.`)
  const videoDir = path.join(epDir, names.video)
  await fs.mkdir(videoDir, { recursive: true })

  const aspect = req.aspect_ratio || 'landscape'
  const nPerPrompt = Math.max(1, Math.min(4, req.number_of_videos_per_prompt || 1))
  const errors: string[] = []
  const isCancelled = () => jq.isCancelled(job.job_id)

  // ── Concurrency pool ───────────────────────────────────────────────────
  // Video clips are expensive ($0.50–$2 each on Veo/Sora). Default to 2
  // in flight — matches fal.ai's starting credit tier — user can bump up
  // to 8 via Settings → Video → Concurrency once their provider account
  // has the credits / quota to handle it.
  const rawConcurrency = Number((config as any).video_concurrency) || 0
  const concurrency = Math.max(1, Math.min(8, rawConcurrency || 2))
  if (prompts.length > 1) {
    job.output_lines.push(
      `Pool: ${Math.min(concurrency, prompts.length)} in parallel (configure via Settings → Video → Concurrency)`,
    )
  }

  async function processPrompt(index: number): Promise<void> {
    if (isCancelled()) return
    const p = prompts[index]!
    const stem = `${code}_Video${p.number.toString().padStart(2, '0')}`

    // A matching `.mp4` of non-zero size is a cache hit. A zero-byte file
    // from a prior aborted download is NOT — we re-run instead of leaving
    // the assembly step to choke on a truncated clip.
    const existing = await fs.readdir(videoDir).catch(() => [])
    const candidate = existing.find(f => f.startsWith(stem) && f.endsWith('.mp4'))
    if (!req.force && candidate && await fileExistsWithContent(path.join(videoDir, candidate))) {
      job.output_lines.push(`Skipping ${stem} (exists)`)
      return
    }

    job.output_lines.push(`[${index + 1}/${prompts.length}] ${p.title || `Clip ${p.number}`}`)

    try {
      const startImage = mode === 'frames'
        ? sceneImages.find(s => s.number === p.number) || sceneImages[index % sceneImages.length]
        : undefined

      const result = await provider.generateVideo({
        mode,
        prompt: p.prompt,
        apiKey,
        aspectRatio: aspect,
        numberOfVideos: nPerPrompt,
        modelId,
        startImagePath: startImage?.path,
        isCancelled,
      })

      // Persist the provider task ids so the Repair button can later
      // recover any clip that failed to download without re-billing the
      // user. One manifest entry per output filename.
      const taskIds = result.taskIds || []
      const providerId = provider.meta.providerId || provider.meta.id
      for (let v = 0; v < result.videoUrls.length; v++) {
        const filename = `${stem}_v${v + 1}.mp4`
        const taskId = taskIds[v] || taskIds[0] || ''
        if (taskId) {
          await recordTask(videoDir, filename, {
            provider: providerId,
            task_id: taskId,
            submitted_at: new Date().toISOString(),
            input_hash: hashInput(p.prompt),
            ...(result.videoUrls[v] ? { result_url: result.videoUrls[v] } : {}),
          })
        }
      }

      for (let v = 0; v < result.videoUrls.length; v++) {
        const savePath = path.join(videoDir, `${stem}_v${v + 1}.mp4`)
        if (!req.force && await fileExistsWithContent(savePath)) continue
        await downloadVideo(result.videoUrls[v], savePath)
        job.output_lines.push(`  Saved ${path.basename(savePath)}`)
      }
    } catch (e: any) {
      // Settled-pool semantics: one clip failure doesn't kill the batch.
      job.output_lines.push(`  Failed: ${e.message}`)
      errors.push(`${p.title || `Clip ${p.number}`}: ${e.message}`)
    }
  }

  let cursor = 0
  async function worker(): Promise<void> {
    while (cursor < prompts.length) {
      if (isCancelled()) return
      const i = cursor++
      await processPrompt(i)
    }
  }
  await Promise.all(
    Array.from({ length: Math.min(concurrency, prompts.length) }, () => worker()),
  )
  void sleepCancellable  // kept imported for any future pacing needs

  // Partial-failure semantics: throw so the queue stamps status='error'
  // instead of 'done'. Same contract as images/audio generators. The queue's
  // own cancel check covers the cancelled case.
  if (errors.length) {
    job.output_lines.push(`Completed with ${errors.length} error(s)`)
    const preview = errors.slice(0, 3).join('; ')
    const suffix = errors.length > 3 ? `; +${errors.length - 3} more` : ''
    throw new Error(`${errors.length} clip(s) failed: ${preview}${suffix}`)
  }
  job.output_lines.push(`All clips saved to: ${videoDir}`)
  job.output_dir = videoDir
}
